import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Alert from "../../ui/alert";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [h.Attribute("dir", "rtl"), h.Class("grid gap-3 text-right")],
    [
      Alert.view<Message>({
        title: "تم الدفع بنجاح",
        description:
          "تمت معالجة دفعتك البالغة 29.99 دولارًا. تم إرسال إيصال إلى عنوان بريدك الإلكتروني.",
        icon: "✓",
      }),
      Alert.view<Message>({
        title: "ميزة جديدة متاحة",
        description:
          "لقد أضفنا دعم الوضع الداكن. يمكنك تفعيله في إعدادات حسابك.",
        icon: "i",
      }),
    ]
  );
});

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeApplication({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Alert RTL",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import { init, update, view } from "./main";

describe("alert-rtl example", () => {
  test("renders the shadcn RTL alert copy", () => {
    const [model] = init();

    Scene.scene(
      { update, view },
      Scene.with(model),
      Scene.expect(Scene.text("تم الدفع بنجاح")).toExist(),
      Scene.expect(
        Scene.text(
          "تمت معالجة دفعتك البالغة 29.99 دولارًا. تم إرسال إيصال إلى عنوان بريدك الإلكتروني."
        )
      ).toExist(),
      Scene.expect(Scene.text("ميزة جديدة متاحة")).toExist(),
      Scene.expect(
        Scene.text("لقد أضفنا دعم الوضع الداكن. يمكنك تفعيله في إعدادات حسابك.")
      ).toExist(),
      Scene.expect(Scene.text("تم الدفع بنجاح")).not.toHaveHandler("click")
    );
  });
});
